"def classify_disability_model(text):
    """
    Identify whether disability framed as medical problem or social barrier
    """

    model_indicators = {
        'medical_model_score': 0,
        'social_model_score': 0,
        'framing': None
    }

    # MEDICAL MODEL: Disability is individual pathology
    medical_patterns = [
        'suffers from', 'afflicted with', 'overcome disability',
        'confined to wheelchair', 'victim of', 'abnormal',
        'disorder', 'impairment', 'defect'
    ]

    # SOCIAL MODEL: Disability is social oppression
    social_patterns = [
        'wheelchair user', 'inaccessible environment',
        'barriers to participation', 'ableism', 'disabled by society',
        'accommodation needed', 'systemic exclusion'
    ]

    for pattern in medical_patterns:
        if pattern in text.lower():
            model_indicators['medical_model_score'] += 1

    for pattern in social_patterns:
        if pattern in text.lower():
            model_indicators['social_model_score'] += 1

    if model_indicators['medical_model_score'] > model_indicators['social_model_score'] * 2:
        model_indicators['framing'] = 'PREDOMINANTLY_MEDICAL'
        model_indicators['monoculture_optimization_risk'] = 'ELEVATED'

    return model_indicators",

"class ASAS:
    def detect_defects(self, action, reasoning):
        """Returns binary flags D1-D6"""
        return {
            'D1': self.detect_trust_missing(reasoning),
            'D2': self.detect_future_blindness(action),
            'D3': self.detect_feedback_omission(reasoning),
            'D4': self.detect_unpriced_externality(action),
            'D5': self.detect_false_success(action),
            'D6': self.detect_extraction_pattern(action)
        }

    def calculate_EDS(self, defects):
        """Equation Defect Score"""
        return sum(defects.values()) / 6

    def calculate_TES(self, history):
        """Trust Effectiveness Score"""
        dependability = history.successes / history.attempts
        transparency = history.accurate_reports / history.reports
        return dependability * transparency",

"class PolicyEngine:
    def decide_action(self, proposed_action, assessment):
        """
        Determines final action based on governance assessment
        """
        eds = assessment['EDS']
        erv = assessment['ERV']
        structural_health = assessment['structural_health']
        trust = assessment['TES']

        # Critical defects → Block
        if eds > 0.5 or erv > 0.5 or structural_health < 0.5:
            return {
                'action': 'block',
                'reason': 'Critical structural defect',
